import { CalendarDays, CalendarRange, Search } from "lucide-react";
import { cn } from "@/lib/cn";

// KMP-C1 (specs/KMP-C1-tab-bar.md). Exactly three tabs as links in a navigation list: not ARIA tabs, no badges, no disabled state.
// `active` is fed by navigation state (a Dish screen opened from Search keeps Search lit). Bottom padding adds the platform inset (conventions 15).
// Sticky at the bottom of its scroll container so it keeps its own space; the page needs no separate reserve.

export type TabId = "today" | "week" | "search";

export type TabBarProps = {
  active: TabId;
  hrefs: Record<TabId, string>;
  onNavigate?: (tab: TabId, event: React.MouseEvent<HTMLAnchorElement>) => void;
  /** Landmark name (Q: "Main"). */
  label?: string;
  labels?: Record<TabId, string>;
};

const tabs = [
  { id: "today", Icon: CalendarDays },
  { id: "week", Icon: CalendarRange },
  { id: "search", Icon: Search },
] as const;

export function TabBar({ active, hrefs, onNavigate, label = "Main", labels = { today: "Today", week: "Week", search: "Search" } }: TabBarProps) {
  return (
    <nav
      aria-label={label}
      className="sticky bottom-0 z-sticky border-t-bw-default border-border bg-surface-raised pb-[calc(env(safe-area-inset-bottom)+var(--shamallya-semantic-space-inset-md))] font-body leading-normal"
    >
      <ul role="list" className="flex">
        {tabs.map(({ id, Icon }) => {
          const on = id === active;
          return (
            <li key={id} className="flex-1">
              <a
                href={hrefs[id]}
                aria-current={on ? "page" : undefined}
                onClick={(e) => onNavigate?.(id, e)}
                className={cn(
                  "group flex min-h-control flex-col items-center justify-center gap-1 px-inset-sm text-center text-ui-floor [overflow-wrap:anywhere]",
                  // the tab's own :hover / :active, so the whole tab (icon, padding, label) underlines the label, not just the label text
                  "[@media(hover:hover)]:[&:hover_.tab-label]:underline [&:active_.tab-label]:underline active:bg-surface-sunken active:text-text",
                  "focus-visible:outline focus-visible:outline-ring focus-visible:outline-offset-ring-inside focus-visible:outline-focus-ring",
                  on ? "font-semibold text-primary-text" : "font-medium text-text-muted",
                )}
              >
                <Icon aria-hidden="true" className={cn("size-icon-lg", on ? "stroke-icon-active" : "stroke-icon")} />
                <span className="tab-label">{labels[id]}</span>
              </a>
            </li>
          );
        })}
      </ul>
    </nav>
  );
}
